<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Notice; use Illuminate\Http\Request;
class NoticeController extends Controller { public function index(){return Notice::orderByDesc('pinned')->orderByDesc('date')->get();} public function store(Request $r){$d=$r->validate(['title'=>'required|max:80','body'=>'required|max:400','date'=>'nullable|date','pinned'=>'boolean']); $d['date']=$d['date']??now()->toDateString(); return Notice::create($d);} public function show(Notice $notice){return $notice;} public function update(Request $r,Notice $notice){$notice->update($r->validate(['title'=>'sometimes|max:80','body'=>'sometimes|max:400','date'=>'sometimes|date','pinned'=>'boolean'])); return $notice;} public function destroy(Notice $notice){$notice->delete(); return response()->noContent();} }
